import{_ as a,o as l,c as r,a4 as i}from"./chunks/framework.BabNWGMA.js";const b=JSON.parse('{"title":"🎯 学习计划","description":"","frontmatter":{},"headers":[],"relativePath":"plan.md","filePath":"plan.md","lastUpdated":1787614642000}'),e={name:"plan.md"};function d(o,t,n,h,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="🎯-学习计划" tabindex="-1">🎯 学习计划 <a class="header-anchor" href="#🎯-学习计划" aria-label="Permalink to &quot;🎯 学习计划&quot;">​</a></h1><blockquote><p>目标:华中科技大学考研(数学一 + 机械原理专业课 + 英语一)+ 炼油化工设备技术员层次 本文件是学习系统执行的依据,每日任务按此推进。2026-08-08 用户确认&quot;按计划进行&quot;。 ⏰ <strong>2026-08-16 用户设定:所有学习目标提前 30 天完成</strong>(考试 12-26,学习主体 11-25 前结束,11-26~12-25 为 30 天自由复习缓冲期)</p></blockquote><h2 id="一、总体框架-三阶段-缓冲期" tabindex="-1">一、总体框架(三阶段 + 缓冲期) <a class="header-anchor" href="#一、总体框架-三阶段-缓冲期" aria-label="Permalink to &quot;一、总体框架(三阶段 + 缓冲期)&quot;">​</a></h2><h3 id="阶段一-·-基础扫盲-2026-08-08-09-15-约-5-5-周" tabindex="-1">阶段一 · 基础扫盲(2026-08-08 ~ 09-15,约 5.5 周) <a class="header-anchor" href="#阶段一-·-基础扫盲-2026-08-08-09-15-约-5-5-周" aria-label="Permalink to &quot;阶段一 · 基础扫盲(2026-08-08 ~ 09-15,约 5.5 周)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>科目</th><th>内容</th><th>节奏</th></tr></thead><tbody><tr><td>高等数学</td><td>极限→导数→一元积分→微分方程→多元微积分→级数→线代→概率</td><td>每周 2-3 个专题(优先保证)</td></tr><tr><td>机械原理</td><td>机构分析→运动学→力分析→齿轮/轮系→平衡→调速</td><td>每周 2 个专题</td></tr><tr><td>炼油化工设备</td><td>泵/压缩机/风机/离心机 原理+结构+选型+故障</td><td>每周 1-2 个专题</td></tr><tr><td>英语</td><td>每日 8 新词 + 1 长难句(系统标配);词汇总量争取 2500+</td><td>每天</td></tr></tbody></table><h3 id="阶段二-·-强化真题-2026-09-16-10-19-约-5-周" tabindex="-1">阶段二 · 强化真题(2026-09-16 ~ 10-19,约 5 周) <a class="header-anchor" href="#阶段二-·-强化真题-2026-09-16-10-19-约-5-周" aria-label="Permalink to &quot;阶段二 · 强化真题(2026-09-16 ~ 10-19,约 5 周)&quot;">​</a></h3><ul><li>高数/机械:华科真题题型专项(计算题、证明题)</li><li>设备:结合催化裂化装置现场案例</li><li>英语:阅读理解真题精做</li></ul><h3 id="阶段三-·-冲刺模拟-2026-10-20-11-25-约-5-周" tabindex="-1">阶段三 · 冲刺模拟(2026-10-20 ~ 11-25,约 5 周) <a class="header-anchor" href="#阶段三-·-冲刺模拟-2026-10-20-11-25-约-5-周" aria-label="Permalink to &quot;阶段三 · 冲刺模拟(2026-10-20 ~ 11-25,约 5 周)&quot;">​</a></h3><ul><li>全真模拟 + 错题总复习</li><li>高频考点背诵 + 英语作文模板</li></ul><h3 id="🕐-缓冲期-2026-11-26-12-25-30-天" tabindex="-1">🕐 缓冲期(2026-11-26 ~ 12-25,30 天) <a class="header-anchor" href="#🕐-缓冲期-2026-11-26-12-25-30-天" aria-label="Permalink to &quot;🕐 缓冲期(2026-11-26 ~ 12-25,30 天)&quot;">​</a></h3><ul><li>自由复习:错题本清零、薄弱知识点最后扫尾、考前心态调整</li><li>每周保持轻量复习(light 模式)防止遗忘,不再推送新内容</li></ul><h2 id="二、执行机制-系统自动" tabindex="-1">二、执行机制(系统自动) <a class="header-anchor" href="#二、执行机制-系统自动" aria-label="Permalink to &quot;二、执行机制(系统自动)&quot;">​</a></h2><ul><li>每日 30min 动态模式:light(15min)/ standard(30min)/ intensive(60min)</li><li>科目轮换:周一高数+设备 / 周二机械+英语 / 周三高数+机械 / 周四英语+设备 / 周五高数+英语 / 周六机械+设备 / 周日总结+错题复习</li><li>定时任务:06:00 晨间询问 → 06:30 知识点推送 → <strong>07:30 / 13:30 / 19:00 三次小测</strong>(上海时间)→ 20:00 复盘 → 周日周报</li><li>错题间隔复习:1/3/7/14 天自动</li></ul><h2 id="三、优先级策略-用户确认" tabindex="-1">三、优先级策略(用户确认) <a class="header-anchor" href="#三、优先级策略-用户确认" aria-label="Permalink to &quot;三、优先级策略(用户确认)&quot;">​</a></h2><ol><li><strong>高数最优先</strong>(分值最高、掌握度最低 10%) <ul><li>建议周六/周日至少一天切 intensive 专攻高数专题</li></ul></li><li><strong>英语词汇加速</strong>:每日系统 8 词基础上,建议额外背 15-20 词(可让系统生成词汇表)</li><li><strong>设备科保持</strong>:掌握度 50% 领先,维持节奏即可</li></ol><h2 id="四、阶段目标-掌握度" tabindex="-1">四、阶段目标(掌握度) <a class="header-anchor" href="#四、阶段目标-掌握度" aria-label="Permalink to &quot;四、阶段目标(掌握度)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间点</th><th>高数</th><th>机械原理</th><th>英语</th><th>设备</th></tr></thead><tbody><tr><td>09-15(阶段一末·提前30天)</td><td>40%</td><td>40%</td><td>50%</td><td>60%</td></tr><tr><td>10-19(阶段二末·提前30天)</td><td>65%</td><td>65%</td><td>70%</td><td>75%</td></tr><tr><td>11-25(冲刺末·提前30天)</td><td>85%+</td><td>85%+</td><td>85%+</td><td>85%+</td></tr></tbody></table><h2 id="当前周计划-2026-08-31-09-06-动态调整版·由-2026-08-30-周报生成" tabindex="-1">当前周计划(2026-08-31 ~ 09-06,动态调整版·由 2026-08-30 周报生成) <a class="header-anchor" href="#当前周计划-2026-08-31-09-06-动态调整版·由-2026-08-30-周报生成" aria-label="Permalink to &quot;当前周计划(2026-08-31 ~ 09-06,动态调整版·由 2026-08-30 周报生成)&quot;">​</a></h2><h3 id="下周动态调整清单-数据源-weekly-archive-py-summary-2026-08-30" tabindex="-1">下周动态调整清单(数据源:weekly_archive.py --summary,2026-08-30) <a class="header-anchor" href="#下周动态调整清单-数据源-weekly-archive-py-summary-2026-08-30" aria-label="Permalink to &quot;下周动态调整清单(数据源:weekly_archive.py --summary,2026-08-30)&quot;">​</a></h3><p><strong>📈 科目优先级(按薄弱程度调整)</strong></p><ol><li><strong>英语(均值 48% &lt;50%,最弱科目,差距 3.8 分)→ 加量、优先级上调</strong>:每日新词 8→12 个;长难句每日 1 题(by which 定语从句优先);词汇库统计 0 词,本周启动系统入库,周目标 ≥50 词</li><li><strong>高等数学(均值 54%,已超 09-15 目标 40%)→ 保持高优先级</strong>:按计划推进专题,到期复习优先,不额外加量</li><li><strong>机械原理(均值 51%,已超 09-15 目标 40%)→ 达标保持</strong>:定轴轮系传动比专项重测</li><li><strong>炼油化工设备(均值 60%,已达 09-15 目标 60%)→ 维持,只保间隔复习,不再加量</strong></li></ol><p><strong>🎯 薄弱知识点专项(下周至少重测 1 次)</strong></p><ul><li>英语:长难句 by which 定语从句(错题 Top1+Top3,共 2 条)→ 专项讲解 + 重测</li><li>机械:定轴轮系传动比计算(错题 Top2)→ 重测 1 次</li><li>其余掌握度 &lt;40% 知识点:每日到期复习优先覆盖,发现即纳入专项重测</li></ul><p><strong>📋 错题重测(未解决 17 条 &gt;5,可执行参数已设:错题必测每天 4 条,即每科 1 题,约 4-5 天清完)</strong></p><ul><li>周一~周四:每天 4 条(高数/机械/英语/设备 各 1 条),英语 by which 长难句 2 条最先清</li><li>周五~周六:继续按错题本顺序轮转,直到清完 17 条</li><li>周日:本周错题总复盘 + 未清项滚动到下周</li></ul><p><strong>📅 到期复习(55 个,每天 1-2 个优先,按轮换科目;英语/高数到期优先于机械/设备)</strong></p><ul><li>周一:高数 2 + 设备 1 | 周二:机械 1 + 英语 2 | 周三:高数 2 + 机械 1 | 周四:英语 2 + 设备 1 | 周五:高数 2 + 英语 1 | 周六:机械 1 + 设备 1 | 周日:错题总复习 + 未清到期滚动</li></ul><p><strong>✅ 可衡量周目标</strong>:英语掌握度 ≥55%;英语新词入库 ≥50;长难句/定轴轮系重测通过;错题本 ≤10 条;本周学习天数 ≥5 天</p>',28)])])}const p=a(e,[["render",d]]);export{b as __pageData,p as default};
